-- PRODUCTOS (catalogo representativo; puede ampliarse con el mismo patron)

-- EXISTENCIAS (arrancan en 0; se llenan con movimientos de compra reales)
SELECT id_producto, 0, 3, 0 FROM producto
WHERE NOT EXISTS (SELECT 1 FROM existencia e WHERE e.id_producto = producto.id_producto);

-- PROVEEDORES

-- CLIENTES (nombre y correo reales asignados desde el INSERT; el ultimo
-- cliente, Jorge Cabrera, se deja intencionalmente sin ventas)

-- COMPRAS

-- DETALLE_COMPRA

-- MOVIMIENTOS DE INVENTARIO: ENTRADAS (una por cada detalle_compra)

-- VENTAS

-- DETALLE_VENTA (las cantidades nunca superan el stock ya ingresado por compras)

-- MOVIMIENTOS DE INVENTARIO: SALIDAS (solo para ventas CONFIRMADAS;
-- una venta ANULADA nunca genera salida de inventario)

-- PAGOS Y COMPROBANTES (solo para ventas CONFIRMADAS)

-- SOLICITUDES DE PRODUCTO

-- BITACORA (bloque unico y consolidado; incluye el registro de la
-- venta anulada, ya resuelto en el propio INSERT de venta arriba)

-- Materializacion final de existencia a partir de los movimientos.
-- No es un parche: es el cierre normal del proceso, y por construccion
-- (las salidas nunca superan lo ya ingresado) el resultado jamas es negativo.
UPDATE existencia e
SET stock_actual = COALESCE((
        SELECT SUM(CASE WHEN mi.tipo = 'ENTRADA' THEN mi.cantidad ELSE -mi.cantidad END)
        FROM movimiento_inventario mi WHERE mi.id_producto = e.id_producto
    ), 0),
    costo_promedio = COALESCE((
        SELECT AVG(mi.costo_unitario) FROM movimiento_inventario mi
        WHERE mi.id_producto = e.id_producto AND mi.tipo = 'ENTRADA'
    ), 0);

COMMIT;
